import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
const root = 'C:/code/chainlesschain', isolated = `${root}/.work/r32`;
const sha = file => createHash('sha256').update(fs.readFileSync(file)).digest('hex');
const read = file => JSON.parse(fs.readFileSync(path.join(root, file)));
const normalize = file => path.relative(isolated, file).replaceAll('\\', '/');
function summarize(report) {
  const files = report.testResults.map(suite => ({ path: normalize(suite.name), status: suite.status,
    passed: suite.assertionResults.filter(item => item.status === 'passed').length,
    skipped: suite.assertionResults.filter(item => ['pending','skipped'].includes(item.status)).length,
    failed: suite.assertionResults.filter(item => item.status === 'failed').length,
    cases: suite.assertionResults.map(item => ({ title: item.fullName, status: item.status, durationMs: item.duration, failureMessages: item.failureMessages })),
  }));
  for (const [field, key] of [['passed','numPassedTests'],['skipped','numPendingTests'],['failed','numFailedTests']])
    assert.equal(files.reduce((sum, file) => sum + file[field], 0), report[key]);
  assert.equal(report.numPassedTests + report.numPendingTests + report.numFailedTests, report.numTotalTests);
  return files;
}
export function collectWindowsCoverage() {
  const checkpointPath = '.work/rrsi-manifest-directory-source-checkpoint.json', checkpoint = read(checkpointPath);
  const originalPath = '.work/rrsi-manifest-directory-final-controls.json', original = read(originalPath);
  const retestPath = '.work/rrsi-manifest-directory-v2-journal-retest.json', retest = read(retestPath);
  assert.equal(original.success, false); assert.equal(original.numFailedTests, 1);
  assert.equal(original.numPassedTests, 323); assert.equal(original.numPendingTests, 13);
  const originalFiles = summarize(original), retestFiles = summarize(retest);
  assert.deepEqual(originalFiles.map(file => file.path).sort(), checkpoint.testFiles.map(file => `packages/cli/${file}`).sort());
  assert.equal(originalFiles.filter(file => file.status === 'failed').length, 1);
  assert.equal(originalFiles.filter(file => file.status === 'passed').length, 9);
  const failedFile = originalFiles.find(file => file.status === 'failed');
  assert.equal(failedFile.path, 'packages/cli/__tests__/unit/evolution-ledger-v2-journal.test.js');
  const failures = failedFile.cases.filter(item => item.status === 'failed'); assert.equal(failures.length, 1);
  assert.ok(failures[0].title.includes('migrates and reopens existing slash-bearing tenant, artifact and audience scopes'));
  assert.ok(failures[0].failureMessages.some(message => message.includes('[windows-acl:timeout-traversal]') &&
    message.includes('ensurePrivateDirectory') && message.includes('createEvolutionLedgerFileManifestCatalogBackend') &&
    message.includes('evolution-ledger-file-manifest-catalog.js:80:25') && message.includes('evolution-ledger-v2-journal.test.js:90:41')));
  assert.ok(original.startTime >= Date.parse(checkpoint.recordedAt));
  assert.ok(retest.startTime > Math.max(...original.testResults.map(suite => suite.endTime)));
  assert.equal(retest.success, true); assert.equal(retest.numFailedTests, 0); assert.equal(retest.numFailedTestSuites, 0);
  assert.equal(retest.numPassedTests, 14); assert.equal(retest.numPendingTests, 0); assert.equal(retest.numTotalTests, 14);
  assert.equal(retestFiles.length, 1); assert.equal(retestFiles[0].path, failedFile.path); assert.equal(retestFiles[0].status, 'passed');
  assert.ok(retestFiles[0].cases.every(item => item.status === 'passed'));
  assert.deepEqual(retestFiles[0].cases.map(item => item.title).sort(), failedFile.cases.map(item => item.title).sort());
  const files = [...originalFiles.filter(file => file.status === 'passed').map(file => ({ ...file, sourceRun: 'original-full-run', reportPath: originalPath })),
    { ...retestFiles[0], sourceRun: 'complete-file-retest', reportPath: retestPath }];
  assert.equal(files.length, 10); assert.equal(new Set(files.map(file => file.path)).size, 10);
  assert.deepEqual(files.map(file => file.path).sort(), checkpoint.testFiles.map(file => `packages/cli/${file}`).sort());
  assert.ok(files.every(file => file.status === 'passed' && file.failed === 0));
  for (const entry of checkpoint.sourceDigests) assert.equal(sha(path.join(isolated, entry.path)), entry.sha256, entry.path);
  return {
    schema: 'chainlesschain.rrsi-local-windows-whole-file-coverage/v1', mode: 'ten-files-covered-across-two-runs',
    sourceCheckpointSha256: sha(path.join(root, checkpointPath)), collectorSha256: sha(fileURLToPath(import.meta.url)),
    runCount: 2, fileCount: files.length, passedCases: files.reduce((sum, file) => sum + file.passed, 0),
    skippedCases: files.reduce((sum, file) => sum + file.skipped, 0), failedCasesInSelectedSuccessfulFiles: 0,
    accounting: 'Nine complete successful files from the original full run plus one complete fourteen-case file retest, counted once per file against unchanged frozen source. Original failed run is retained. This is not a single clean full run or an Actions release gate. Preliminary cases, the original thirteen passes in the retried file, WSL and compatibility probes do not add to coverage totals',
    originalFullRun: { reportPath: originalPath, reportSha256: sha(path.join(root, originalPath)), success: false, exitCode: 1,
      runnerArgs: ['run', ...checkpoint.testFiles, '--maxWorkers=1', '--reporter=default', '--reporter=json', '--outputFile=C:/code/chainlesschain/.work/rrsi-manifest-directory-final-controls.json'],
      startTime: original.startTime, testFiles: checkpoint.testFiles, passedCases: original.numPassedTests,
      failedCases: original.numFailedTests, skippedCases: original.numPendingTests, passedFiles: 9, failedFiles: 1, files: originalFiles,
      failures, failureStage: 'Initial migrated fixture construction at test line 90: ensurePrivateDirectory for manifest catalog times out in Windows ACL traversal before the new stateReader/capability is created. The deeper cause of the native subprocess timeout is not established' },
    completeFileRetest: { reportPath: retestPath, reportSha256: sha(path.join(root, retestPath)), success: true, exitCode: 0,
      startTime: retest.startTime, file: failedFile.path, passedCases: 14, failedCases: 0, skippedCases: 0,
      command: 'node C:/code/chainlesschain/node_modules/vitest/vitest.mjs run __tests__/unit/evolution-ledger-v2-journal.test.js --maxWorkers=1 --reporter=default --reporter=json --outputFile=<retest.json>',
      unchangedSourceTestsRunnerFlagsAndBudgets: true, noTestFilter: true, files: retestFiles },
    files,
  };
}

