import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { fileURLToPath, pathToFileURL } from 'node:url';
const root = '/mnt/c/code/chainlesschain', isolated = `${root}/.work/r32`;
const checkpointPath = `${root}/.work/rrsi-manifest-directory-source-checkpoint.json`;
const checkpoint = JSON.parse(fs.readFileSync(checkpointPath));
const sha = file => createHash('sha256').update(fs.readFileSync(file)).digest('hex');
const verify = () => { for (const entry of checkpoint.sourceDigests) assert.equal(sha(path.join(isolated, entry.path)), entry.sha256, entry.path); };
verify(); assert.equal(process.platform, 'linux');
const runnerSha256 = sha(fileURLToPath(import.meta.url));
const catalog = await import(pathToFileURL(`${isolated}/packages/cli/src/lib/evolution/evolution-ledger-file-manifest-catalog.js`));
const head = await import(pathToFileURL(`${isolated}/packages/cli/src/lib/evolution/evolution-ledger-file-manifest-head-store.js`));
const temp = fs.realpathSync.native(os.tmpdir()), directory = fs.mkdtempSync(path.join(temp, 'cc-manifest-cap-posix-'));
const results = [], FAILED = 'CC_EVOLUTION_MANIFEST_STATE_READ_FAILED';
const hash = value => createHash('sha256').update(JSON.stringify(value)).digest('hex');
const safe = target => { assert.ok(path.resolve(target).startsWith(directory + path.sep)); };
try {
  for (const [role, create, capture] of [
    ['catalog', catalog.createEvolutionLedgerFileManifestCatalogBackend, catalog.captureEvolutionLedgerFileManifestCatalogDirectoryBoundary],
    ['head', head.createEvolutionLedgerFileManifestHeadBackend, head.captureEvolutionLedgerFileManifestHeadDirectoryBoundary],
  ]) {
    const target = path.join(directory, role), file = path.join(target, `manifest-${role}.json`);
    let armed = false, calls = [], forbidden = [];
    const fsImpl = { ...fs };
    for (const key of Object.keys(fsImpl)) if (typeof fsImpl[key] === 'function') fsImpl[key] = (...args) => {
      if (armed) forbidden.push(key);
      assert.equal(armed, false, `forbidden metadata operation: ${key}`); return fs[key](...args);
    };
    fsImpl.lstatSync = (name, options) => { if (armed) { if (name !== target) forbidden.push('non-directory-lstat'); assert.equal(name, target); calls.push('lstat'); } return fs.lstatSync(name, options); };
    fsImpl.realpathSync = function(name) { assert.equal(this, fsImpl); if (armed) { if (name !== target) forbidden.push('non-directory-realpath'); assert.equal(name, target); calls.push('realpath'); } return fs.realpathSync.native(name); };
    const backend = create({ directoryPath: target, fsImpl }), cap = capture(backend), original = hash(cap.descriptor);
    const read = () => role === 'head' ? backend.load() : backend.list();
    const write = (n, previous) => role === 'head' ? backend.compareAndSet({ expectedHeadDigest: previous, nextHead: { headDigest: `h${n}` } }) : backend.compareAndAppend({ expectedManifestDigest: previous, manifest: { manifestDigest: `m${n}` } });
    write(1, null); write(2, role === 'head' ? 'h1' : 'm1');
    assert.deepEqual(read(), role === 'head' ? { headDigest: 'h2' } : [{ manifestDigest: 'm1' }, { manifestDigest: 'm2' }]);
    assert.equal(hash(capture(create({ directoryPath: target })).descriptor), original);
    armed = true; calls = []; assert.equal(capture(backend), cap); assert.equal(hash(cap.recheck()), original); armed = false;
    assert.deepEqual(calls, ['lstat','realpath','lstat','realpath']);
    assert.deepEqual(forbidden, []);
    results.push({ role, scenario: 'actual-write-rename-read-reopen-and-metadata-only-stability', passed: true, capabilityOpenCalls: 0 });
    for (const fault of ['clone', 'missing', 'symlink', 'fifo']) {
      const saved = path.join(directory, `${role}-saved`); safe(target); safe(saved);
      fs.renameSync(target, saved); let actualFifo = false;
      try {
        if (fault === 'clone') fs.cpSync(saved, target, { recursive: true });
        if (fault === 'symlink') fs.symlinkSync(saved, target, 'dir');
        if (fault === 'fifo') { const result = spawnSync('mkfifo', [target], { encoding: 'utf8', timeout: 10_000 }); assert.equal(result.status, 0, result.stderr); actualFifo = fs.lstatSync(target).isFIFO(); assert.equal(actualFifo, true); }
        armed = true;
        for (const operation of [() => capture(backend), () => cap.recheck()]) assert.throws(operation, error => error.code === FAILED);
        armed = false;
        if (fault === 'missing') assert.equal(fs.existsSync(target), false);
      } finally {
        armed = false;
        if (fault === 'clone') fs.rmSync(target, { recursive: true, force: true });
        else if (fault !== 'missing') fs.unlinkSync(target);
        fs.renameSync(saved, target);
      }
      assert.equal(hash(cap.recheck()), original);
      assert.deepEqual(forbidden, []);
      results.push({ role, scenario: fault, actualFifo, passed: true, capabilityOpenCalls: 0, originalDirectoryDigestRestored: true });
    }
    fs.chmodSync(target, 0o710);
    try { armed = true; assert.throws(() => cap.recheck(), error => error.code === FAILED); }
    finally { armed = false; fs.chmodSync(target, 0o700); }
    assert.equal(hash(cap.recheck()), original);
    assert.deepEqual(forbidden, []);
    results.push({ role, scenario: 'actual-mode-change-and-original-restoration', passed: true, capabilityOpenCalls: 0 });
    const bytes = fs.readFileSync(file);
    try {
      fs.writeFileSync(file, 'invalid state'); assert.equal(hash(cap.recheck()), original); assert.throws(read);
      fs.unlinkSync(file); assert.equal(hash(cap.recheck()), original); assert.deepEqual(read(), role === 'head' ? null : []);
    } finally { fs.writeFileSync(file, bytes, { mode: 0o600 }); }
    results.push({ role, scenario: 'corrupt-and-missing-leaf-is-outside-directory-scope', passed: true });
  }
  const helpers = await import(pathToFileURL(`${isolated}/packages/cli/__tests__/fixtures/evolution-ledger-v2-store.js`));
  const value = helpers.openLedgerV2Fixture(path.join(directory, 'fresh-v2'));
  const captures = [catalog.captureEvolutionLedgerFileManifestCatalogDirectoryBoundary(value.manifest.catalogBackend), head.captureEvolutionLedgerFileManifestHeadDirectoryBoundary(value.manifest.headBackend)];
  const before = captures.map(cap => hash(cap.descriptor));
  const prior = value.journal.verify(); value.journal.appendDomainEvent(helpers.v2FixtureDomainEvent(value, 'native-manifest-capability'));
  assert.equal(value.journal.verify().sequence, prior.sequence + 1);
  assert.deepEqual(captures.map(cap => hash(cap.recheck())), before);
  results.push({ scenario: 'fresh-real-v2-migration-and-domain-append-with-original-raw-components', passed: true, observedTextRegistered: false, fullPhysicalStorageGraphVerified: false });
  verify(); assert.equal(results.length, 15);
  const out = { recordedAt: new Date().toISOString(), platform: process.platform, nodeVersion: process.version, kernel: os.release(),
    passedScenarios: results.length, failures: 0, sourceCheckpointSha256: sha(checkpointPath), sourceDigests: checkpoint.sourceDigests,
    runnerSha256, results, capabilityMetadataOnly: true, fullPhysicalStorageGraphVerified: false, realRrsiAbc: 'NOT_RUN', productionPromotion: 'HOLD' };
  fs.writeFileSync(`${root}/.work/rrsi-manifest-directory-posix.json`, JSON.stringify(out, null, 2) + '\n');
  console.log(JSON.stringify({ passedScenarios: results.length, actualFifos: results.filter(item => item.actualFifo).length }));
} finally {
  assert.equal(path.dirname(directory), temp); assert.ok(path.basename(directory).startsWith('cc-manifest-cap-posix-'));
  fs.rmSync(directory, { recursive: true, force: true });
}

legacyStateProtocolRoundtrip.runnerSource:
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { fileURLToPath, pathToFileURL } from 'node:url';
const root = 'C:/code/chainlesschain', isolated = `${root}/.work/r32`;
const sha = file => createHash('sha256').update(fs.readFileSync(file)).digest('hex');
const checkpoint = JSON.parse(fs.readFileSync(`${root}/.work/rrsi-manifest-directory-source-checkpoint.json`));
const verify = () => { for (const entry of checkpoint.sourceDigests) assert.equal(sha(path.join(isolated, entry.path)), entry.sha256, entry.path); };
verify(); const runnerSha256 = sha(fileURLToPath(import.meta.url));
const originalSourceDigests = checkpoint.changedFiles.filter(file => file.includes('/src/')).map(file => ({ path: file, sha256: sha(path.join(root, file)) }));
for (const entry of originalSourceDigests) assert.equal(entry.sha256, checkpoint.rootBeforePropagation.find(item => item.path === entry.path).sha256);
const temp = fs.realpathSync.native(os.tmpdir()), directory = fs.mkdtempSync(path.join(temp, 'cc-manifest-cap-legacy-'));
const results = [];
try {
  for (const [role, module, factory, capture] of [
    ['catalog', 'evolution-ledger-file-manifest-catalog.js', 'createEvolutionLedgerFileManifestCatalogBackend', 'captureEvolutionLedgerFileManifestCatalogDirectoryBoundary'],
    ['head', 'evolution-ledger-file-manifest-head-store.js', 'createEvolutionLedgerFileManifestHeadBackend', 'captureEvolutionLedgerFileManifestHeadDirectoryBoundary'],
  ]) {
    const relative = `packages/cli/src/lib/evolution/${module}`;
    const old = await import(pathToFileURL(path.join(root, relative))), current = await import(pathToFileURL(path.join(isolated, relative)));
    assert.equal(old[capture], undefined);
    const target = path.join(directory, role), file = path.join(target, `manifest-${role}.json`);
    const original = old[factory]({ directoryPath: target });
    const read = backend => role === 'head' ? backend.load() : backend.list();
    const write = (backend, n) => {
      const value = role === 'head' ? { headDigest: `h${n}` } : { manifestDigest: `m${n}` };
      const result = role === 'head' ? backend.compareAndSet({ expectedHeadDigest: n === 1 ? null : `h${n-1}`, nextHead: value }) : backend.compareAndAppend({ expectedManifestDigest: n === 1 ? null : `m${n-1}`, manifest: value });
      assert.equal(role === 'head' ? result.committed : result.appended, true);
      const expected = role === 'head' ? { headDigest: `h${n}` } : Array.from({ length: n }, (_, i) => ({ manifestDigest: `m${i+1}` }));
      assert.deepEqual(read(backend), expected);
      return result;
    };
    write(original, 1); const bytes1 = fs.readFileSync(file);
    const next = current[factory]({ directoryPath: target }), cap = current[capture](next), originalDescriptor = structuredClone(original.descriptor);
    const component = JSON.stringify(cap.descriptor);
    assert.deepEqual(next.descriptor, originalDescriptor); assert.deepEqual(read(next), read(original)); assert.deepEqual(fs.readFileSync(file), bytes1);
    write(next, 2); const bytes2 = fs.readFileSync(file);
    const reverse = old[factory]({ directoryPath: target }); assert.deepEqual(reverse.descriptor, originalDescriptor);
    assert.deepEqual(read(reverse), read(next)); assert.deepEqual(fs.readFileSync(file), bytes2);
    write(reverse, 3); assert.deepEqual(read(next), read(reverse)); assert.equal(JSON.stringify(cap.recheck()), component);
    assert.deepEqual(next.descriptor, originalDescriptor);
    results.push({ role, oldWritesNewReads: true, newWritesOldReads: true, oldReverseWritesNewReads: true,
      successfulWrites: 3, expectedContentsVerifiedAfterEachWrite: true,
      persistentDescriptorUnchanged: true, stateBytesUnchangedDuringBothReadOnlyWindows: true, originalDirectoryComponentUnchangedAfterRoundtrip: true,
      persistentStateSchema: JSON.parse(fs.readFileSync(file, 'utf8')).schema });
  }
  verify();
  fs.writeFileSync(`${root}/.work/rrsi-manifest-directory-legacy.json`, JSON.stringify({ recordedAt: new Date().toISOString(),
    platform: process.platform, nodeVersion: process.version, runnerSha256, sourceCheckpointSha256: sha(`${root}/.work/rrsi-manifest-directory-source-checkpoint.json`),
    originalSourceDigests, results, allRoundtripAssertionsCompleted: true,
    scope: 'Two original mutable backend state protocols roundtrip across root section-36 modules and isolated section-37 modules in the same original directories; not a deployment upgrade, durable inode pin or complete signed-v2 installation validation',
  }, null, 2) + '\n');
  console.log(JSON.stringify({ roles: results.length, bidirectionalRoundtrip: true }));
} finally {
  assert.equal(path.dirname(directory), temp); assert.ok(path.basename(directory).startsWith('cc-manifest-cap-legacy-'));
  fs.rmSync(directory, { recursive: true, force: true });
}
